package com.eudistack.audit.domain.port.out;

import com.eudistack.audit.domain.model.AuditEvent;
import com.eudistack.audit.domain.model.TenantRef;

/**
 * Writes inside the single transaction of one batch. Nothing is durable until the work returns.
 */
public interface BatchWriter {

    /**
     * Inserts the event in the schema of its tenant unless its {@code event_id} is already there.
     *
     * @param payloadHash hash of the event as received
     */
    InsertOutcome insertIfAbsent(TenantRef tenant, AuditEvent event, byte[] payloadHash);

    /**
     * Inserts an event generated by the API in {@code platform}. When its {@code event_id} already
     * exists, nothing is inserted.
     */
    void insertPlatformEvent(AuditEvent event);
}
